 if(panel==='restore')html=dialog('存档恢复点','保留迁移前旧档',`<p>当前进度不会在预览时被覆盖。先导出，再选择需要的恢复点；旧版 v8 原档另行保留。</p><button data-do="export">导出当前进度</button>${availableRecoveryPoints().map((p,i)=>`<article class="co-card"><b>${i===0?'即时备份':'时间恢复点 '+i}</b><p>${p.level} 级 · 第 ${Math.floor(p.time/300)+1} 天 · 世界时间 ${Math.floor(p.time)} 秒</p><button data-recovery="${p.key}">预览这个恢复点</button></article>`).join('')||'<p>尚无可用恢复点。</p>'}`);
 if(panel==='rescue-confirm')html=dialog('紧急救援','提前告知代价',`<p>回到原岛营火，保留装备、食物、图纸和纪念章，损失 ${hasModule(state,'salvage')?15:30}% 普通材料（数量向下取整）。已完成的观测与见闻仍会结算。入口虫洞免费返回且没有损失。</p><button data-co="rescue" class="danger">确认呼叫救援</button><button data-do="${state.status==='dead'?'menu':'close'}">${state.status==='dead'?'返回菜单':'继续远征'}</button>`);
 overlay.innerHTML=html;const scrollBody=overlay.querySelector('.dialog-body');if(scrollBody)scrollBody.scrollTop=oldScroll;if(panel==='map')view.map($('#large-map'),state,true);
 const focus=overlay.querySelector('button:not(:disabled)');focus?.focus({preventScroll:true});
