const htmlCache=new Map();
function setHTML(selector,html){if(htmlCache.get(selector)!==html){$(selector).innerHTML=html;htmlCache.set(selector,html);}}
function hotItem(id){return id==='spear'?(G.equippedWeapon(state)||'spear'):id==='cooked'?['feast','fishsoup','stew','roast','ration','cooked'].find(k=>state.inventory[k])||id:id==='spear'&&state.inventory.copperSpear?'copperSpear':id;}
const hotIds=['axe','pickaxe','spear','torch','berry','cooked','seed','flower'];
function updateHUD(){
 document.body.classList.toggle('novice-guide',!state.settlements.expert&&guideStage(state)<3);setHTML('#growth-strip',renderRoadmap(state,growthStatus(state).requirements));
 const special=$('[data-do="active-ability"]');special.hidden=state.level<3;document.body.classList.toggle('has-touch-ability',!special.hidden);special.textContent=({dash:'闪步',projection:'投影臂',return:'归途'})[controls.ability];
 updateWildernessHUD();
 const p=state.player;$('#vitals').innerHTML=[['♥','生命',p.hp,G.maxHealth(state),'#dfa18b'],['◒','饱食',p.hunger,100,'#dfc282'],['✧','意识',p.clarity,100,'#b9d9cd']].map(([ic,name,n,max,col])=>`<div class="vital" title="${name} ${Math.round(n)}/${max}" style="--accent:${col}"><div class="line"><em>${ic}</em><small>${name}</small><b>${Math.ceil(n)}</b></div><div class="meter"><i style="width:${Math.max(0,n/max*100)}%"></i></div></div>`).join('');
 const ph=G.phase(state),remaining=ph==='day'?190-state.time%300:ph==='dusk'?230-state.time%300:300-state.time%300;$('#day').textContent='第 '+G.day(state)+' 天';$('#phase').textContent=({day:'白昼',dusk:'黄昏',night:'夜晚'})[ph]+' · '+Math.ceil(remaining)+'s';$('#sun').textContent=ph==='night'?'☾':'☼';
 setHTML('#knowledge',`<span>◇ <b>${G.LEVEL_ROMAN[state.level]} ${G.LEVEL_NAMES[state.level]}</b></span><span>洞见 <b>${Math.floor(state.insight)}</b></span><button data-do="growth" aria-label="共鸣获取指引">共鸣 <b>${Math.floor(state.resonance)}</b> ⓘ</button><button data-do="growth" aria-label="生态恢复指引">生态 <b>${Math.round(state.ecology)}</b> ⓘ</button>`);
 const q=G.getQuest(state);$('#quest').innerHTML=`<div class="eyebrow"><span>荒野手记</span><span>第 ${state.level} 阶 / 九级</span></div><h2>${q.title}</h2><p>${q.text}<br><span style="color:#e0cc9a">${q.progress}</span></p><div class="quest-progress">${Array.from({length:9},(_,i)=>`<i class="${i<state.level?'done':''}"></i>`).join('')}</div>`;$('#quest').title=q.hint;
 $('#location').innerHTML=`⌖ ${G.inHome(state)?G.biome(p.x,p.y).name:G.realm(state).name} <small>${Math.round(p.x)}, ${Math.round(p.y)}</small>`;
 const hotbarHTML=hotIds.map((id,i)=>{id=hotItem(id);const n=state.inventory[id]||0;return`<button class="slot ${!n?'empty':''} ${id==='torch'&&state.torchOn?'active':''}" data-use="${id}" title="${G.ITEMS[id].name}${G.ITEMS[id].food?' · 点击食用':''}${G.ITEMS[id].durability?' · 采集时自动使用':''}" aria-label="${G.ITEMS[id].name}，数量 ${n}" ${!n?'disabled':''}>${icon(id)}<small>${i+1}</small><b>${n||''}</b>${G.ITEMS[id].durability&&n?`<i class="durability" style="width:${state.durability[id]/G.ITEMS[id].durability*100}%"></i>`:''}</button>`;}).join('');setHTML('#hotbar',hotbarHTML);
 const n=G.nearest(state);const contextHTML=placing?'':n?`<button data-do="interact"><kbd>E</kbd> ${NODESAction(n)} · ${(n.type==='trial'?G.TRIALS.find(t=>t.id===n.trialId)?.name:n.type==='encounter'?ENCOUNTERS.find(e=>e.id===n.eventId)?.name:n.type==='fieldsite'?SITE_TYPES[n.siteType]?.name:G.NODES[n.type]?.name)||G.BUILDING_NAMES[n.type]}</button>${n.type==='campfire'?`<button data-do="fuel" class="quick-fuel"><kbd>F</kbd> 添柴 · ${Math.ceil(n.fuel)}s</button>`:''}`:G.phase(state)==='night'&&!G.lightAt(state,p.x,p.y)?'黑暗正在侵蚀意识 · 快点亮火炬或回到营火':state.torchOn?`火炬剩余 ${Math.ceil(state.torchFuel)} 秒 · 点击火炬可熄灭`:'';const alternatives=!panel&&!placing?[...state.nodes.filter(n=>n.available),...state.buildings].filter(o=>G.distance(o,state.player)<95&&o.id!==n?.id).slice(0,3):[];setHTML('#context',contextHTML+(alternatives.length?'<details class="co-nearby"><summary>其他目标 '+alternatives.length+'</summary>'+alternatives.map(o=>'<button data-target="'+o.id+'">'+(G.NODES[o.type]?.name||G.BUILDING_NAMES[o.type])+'</button>').join('')+'</details>':''));
 layoutGrowthStrip();updateAbilities();view.map($('#mini'),state);if(state.message&&state.message.id!==lastMessage){lastMessage=state.message.id;notice(state.message.text);}
}
function layoutGrowthStrip(){
 const strip=$('#growth-strip'),weather=$('#weather').getBoundingClientRect(),knowledge=$('#knowledge').getBoundingClientRect(),quest=$('#quest').getBoundingClientRect(),mobile=document.body.classList.contains('compact-hud');
 const left=mobile?12:Math.max(100,weather.left),top=Math.max(weather.bottom,knowledge.bottom)+6;
 let width=Math.min(530,innerWidth-left-(mobile?112:12));
 if(!mobile&&quest.width&&quest.left>left)width=Math.min(width,quest.left-left-12);
 Object.assign(strip.style,{left:left+'px',top:top+'px',maxWidth:Math.max(150,width)+'px'});
 if(mobile){
  // 成长与菜单依次排在天气下方；右侧为小地图和手记保留位置。
  $('#camp-toolbar').style.top=(top+strip.getBoundingClientRect().height+8)+'px';
  const actions=$('.touch-actions').getBoundingClientRect(),questTop=quest.top||188;
  $('#quest').style.maxHeight=Math.max(70,Math.min(260,actions.top-questTop-8))+'px';
 }else{
  $('#camp-toolbar').style.top='';$('#quest').style.maxHeight='';
 }
}
// 旋转屏幕或展开手记时立即重排，不依赖下一次游戏状态更新。
window.addEventListener('resize',()=>requestAnimationFrame(layoutGrowthStrip));
document.addEventListener('click',e=>{if(e.target.closest('[data-ui="quest-toggle"],#camp-toolbar-toggle'))requestAnimationFrame(layoutGrowthStrip);});
function NODESAction(n){if(n.type==='settlement')return'交谈';if(n.type==='riftanchor')return'观测';if(n.type==='riftevent')return'见闻';if(n.type==='conduit')return'解谜';if(n.type==='wayfarer')return'交谈';if(n.type==='encounter')return'遭遇';if(n.type==='fieldsite')return'探索';if(n.type==='lostpack')return'取回';if(n.type==='fielddesk')return'委托';if(n.type==='wormhole')return'穿越';if(n.type==='pond')return'钓鱼';if(n.type==='burrow')return'查看';return G.NODES[n.type]?(['ruin','trial'].includes(n.type)?'调查':['tree'].includes(n.type)?'砍伐':['rock','ore','crystal'].includes(n.type)?'开采':'采集'):n.type==='farm'?'收获':n.type==='drill'?'取出矿石':'使用';}
async function exportSave(){if(window.__TAURI__?.core?.invoke){try{if(await window.__TAURI__.core.invoke('export_save',{contents:G.serialize(state)}))notice('存档已导出。');}catch(e){notice('导出失败：'+e);}return;}const url=URL.createObjectURL(new Blob([G.serialize(state)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`九级-生存-第${G.day(state)}天.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);notice('存档已导出。');}
function perform(action){
 if(action==='reload-render'){save();location.reload();return;}
 if(action==='guide-promotion'){const type=state.level===1?'resonator':state.level===2?'beacon':G.CHAPTERS[state.level]?.station;const facility=state.buildings.find(b=>b.type===type);if(facility){close();run(G.goTo(state,facility.x,facility.y,facility.id));}else{category=state.level===2?'advanced':'camp';show('craft');notice('先建造'+(G.BUILDING_NAMES[type]||'当前阶段晋升设施')+'，再按成长清单完成条件。');}return;}
 if(action==='guide-toggle'){G.settlementAction(state,'expert');save();if(panel==='guide')close();updateHUD();return;}
 if(action==='villages'){stationId=null;show('villages');return;}
 if(action==='guide'){show('guide');return;}
 if(action==='menu'){show('pause');return;}
 if(action==='active-ability'){perform(controls.ability);return;}
 if(action==='coexist'||action==='controls'){stationId=null;coTab='expedition';show(action);return;}
 if(action==='photo'){cancelBuilding();panel='photo';resetInput();$('#overlay').hidden=true;document.body.classList.add('photo-mode');view.photo=true;$('#photo-tools').hidden=false;return;}
 if(action==='photo-close'){document.body.classList.remove('photo-mode');view.photo=false;$('#photo-tools').hidden=true;close();return;}
 if(action==='photo-save'){const a=document.createElement('a');a.download='九级3.0-'+(state.symbiosis.run?.seed??state.seed)+'.png';a.href=$('#world').toDataURL('image/png');a.click();return;}

 if(action==='consent-on'||action==='consent-off'){telemetry.setConsent(action==='consent-on');if(action==='consent-on')telemetry.flush();notice(action==='consent-on'?'已开启匿名统计，可随时关闭。':'匿名统计已关闭。');close();return;}if(action==='privacy'){show('privacy');return;}
 if(action==='sound'){audio.toggle();updateWildernessHUD();return;}if(action==='fuel'){run(G.quickFuel(state));save();return;}
 if(action==='toggle-repeat'){continuous=!continuous;buildControls();return;}if(action==='toggle-snap'){view.snap=!view.snap;if(placing)buildControls();return;}
 if(action==='recover'){const result=G.recoverAtCamp(state);if(result.ok){deathShown=false;cancelBuilding();close();view.camera={...state.player};}run(result);save();return;}
 if(action==='accept-contract'){run(G.acceptContract(state,stationId));save();return;}
 if(action==='claim-contract'){run(G.claimContract(state));save();return;}
 if(action==='plant'){beginPlanting();return;}
 if(action==='guide-camp'){const camp=growthStatus(state).camp;if(!camp){notice('当前地图还没有营火，请先建造。');return;}cancelBuilding();close();run(G.goTo(state,camp.x,camp.y,camp.id));return;}
 if(action==='meditate-nearby'){const camp=growthStatus(state).camp;const r=G.stationAction(state,'meditate',camp?.id);run(r);if(r.ok)close();return;}
 if(action==='unpin'){state.wilderness.pinned=null;save();updateWildernessHUD();return;}
 if(action==='close'){close();return;}if(action==='start'){if(!hasSave&&!startConfiguredGame())return;close();if(state.status==='dead')show('dead');else if(state.status==='won')show('won');else if(state.settlements.intro<3)show('prologue');return;}
 if(action==='odyssey'){if(inRift(state)){coTab='expedition';stationId=null;show('coexist');return;}if(panel==='odyssey')close();else{stationId=null;odysseyTab='overview';show('odyssey');}return;}
 if(action==='projection'){run(G.odysseyAction(state,'projection'));save();return;}
 if(action==='start-odyssey'){const r=G.startOdyssey(state);if(r.ok){deathShown=false;stationId=null;odysseyTab='overview';show('odyssey');}run(r);save();return;}
 if(action==='pause'){if(!panel)show('pause');else close();return;}if(['craft','tech','bag','map','journey','handbook','bestiary','growth','missions','settlement'].includes(action)){if(panel===action)close();else show(action);return;}
 if(action==='interact'){if(!panel)run(G.interact(state));return;}if(action==='attack'){if(!panel)run(G.attack(state));return;}
 if(action==='cancel-build'){cancelBuilding();return;}if(action==='place-near'){const p=placing==='seed'?G.plantingNearPlayer(state):G.placementNearPlayer(state,placing);if(p)buildAt(p);else notice('附近没有合适的空地，移动后再试。');return;}
 if(action==='dodge'){run(G.dodgeRoll(state,(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0)+moveTouch.x,(keys.has('KeyS')?1:0)-(keys.has('KeyW')?1:0)+moveTouch.y));return;}
 if(action==='cross-rift'){const result=G.enterWormhole(state,stationId);run(result);if(result.ok){cancelBuilding();close();view.camera={...state.player};save();}return;}
 if(action==='dash'){run(G.dash(state,(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0)+moveTouch.x,(keys.has('KeyS')?1:0)-(keys.has('KeyW')?1:0)+moveTouch.y));return;}if(action==='return'){run(G.returnHome(state));save();return;}
 if(action==='dismantle'){show('dismantle');return;}if(action==='confirm-dismantle'){const r=G.dismantle(state,stationId);run(r);if(r.ok)close();return;}
 if(action==='restore'){show('restore');return;}
 if(action==='confirm-restore'){try{const raw=localStorage.getItem(SAVE_KEY+'.backup');if(!raw)throw new Error('尚无备份');const recovered=G.parseSave(raw);storeProgress(localStorage,SAVE_KEY,G.serialize(recovered),G.parseSave);state=recovered;deathShown=false;cancelBuilding();view.camera={...state.player};close();notice('已恢复上一份备份。');}catch(e){notice('无法恢复：'+e.message);}return;}
 if(action==='export'){exportSave();return;}if(action==='import'){if(window.__TAURI__?.core?.invoke){window.__TAURI__.core.invoke('import_save').then(raw=>{if(!raw)return;const imported=G.parseSave(raw);storeProgress(localStorage,SAVE_KEY,G.serialize(imported),G.parseSave);state=imported;deathShown=false;lastMessage=-1;cancelBuilding();view.camera={...state.player};close();notice('存档已导入。');}).catch(e=>notice('导入失败：'+e));}else $('#import-file').click();return;}if(action==='new'){show('new');return;}
 if(action==='confirm-new'){if(!startConfiguredGame())return;deathShown=false;lastMessage=-1;cancelBuilding();view.camera={...state.player};save();close();show('prologue');notice('先拾取身边的树枝和燧石，合成石斧。');return;}
 if(action==='freeplay'){state.status='playing';if(G.isOdyssey(state)&&state.expansion.ending==='stay')state.odyssey.creative=true;deathShown=false;close();save();}
}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b||b.disabled)return;audio.unlock();
 if(b.dataset.villageTab){stationId='village-'+b.dataset.villageTab;renderPanel();return;}
 if(b.dataset.villageAction){const r=G.settlementAction(state,b.dataset.villageAction,b.dataset.villageId||'',b.dataset.value||'');run(r);if(r.ok&&['intro','skip'].includes(b.dataset.villageAction)&&state.settlements.intro===3)close();else if(r.ok&&b.dataset.villageAction==='replay')show('prologue');save();return;}
 if(b.dataset.campaign){newCampaign=b.dataset.campaign;renderPanel();return;}
 if(b.dataset.civTab){odysseyTab=b.dataset.civTab;renderPanel();return;}
 if(b.dataset.civObject){stationId=b.dataset.civObject;odysseyTab='industrial';show('odyssey',stationId);return;}
 if(b.dataset.civWalk){const object=[...state.nodes,...state.buildings].find(n=>n.id===b.dataset.civWalk);if(object){close();run(G.goTo(state,object.x,object.y,object.id));}return;}
 if(b.hasAttribute('data-civ-create-route')){run(G.odysseyAction(state,'route-add',$('#cargo-destination').value,$('#cargo-item').value,Number($('#cargo-count').value)));save();return;}
 if(b.dataset.odysseyAction){run(G.odysseyAction(state,b.dataset.odysseyAction,b.dataset.id,b.dataset.value,Number(b.dataset.count||1)));save();return;}
 if(b.dataset.difficulty){if(panel==='welcome'&&!hasSave){state.homestead.mode=b.dataset.difficulty;newDifficulty=b.dataset.difficulty;}else if(panel==='new')newDifficulty=b.dataset.difficulty;renderPanel();return;}
 if(b.dataset.encounterChoice){const n=state.nodes.find(n=>n.id===stationId);const r=G.chooseEncounter(state,n?.eventId,b.dataset.encounterChoice);run(r);if(r.ok)show('settlement');save();return;}
 if(b.dataset.delivery){run(G.claimDelivery(state,b.dataset.delivery));save();return;}
 if(b.dataset.walkFacility){const bld=[...state.buildings,...state.nodes].find(x=>x.id===b.dataset.walkFacility);if(bld){close();run(G.goTo(state,bld.x,bld.y,bld.id));}return;}
 if(b.dataset.contract){run(G.acceptContract(state,b.dataset.contract));save();return;}
 if(b.dataset.siteChoice){const result=G.beginSite(state,stationId,b.dataset.siteChoice);run(result);if(result.ok)close();save();return;}
 if(b.dataset.specialty){const [weapon,id]=b.dataset.specialty.split(':');run(G.chooseSpecialty(state,weapon,id));save();return;}
 if(b.dataset.claim){run(G.claimHandbook(state,b.dataset.claim));save();return;}
 if(b.dataset.coTab){coTab=b.dataset.coTab;stationId=null;renderPanel();$('.dialog-body').scrollTop=0;return;}
 if(b.hasAttribute('data-co-rescue')){show('rescue-confirm');return;}
 if(b.dataset.coWalk){const n=[...state.nodes,...state.buildings].find(n=>n.id===b.dataset.coWalk);if(n){close();run(G.goTo(state,n.x,n.y,n.id));}return;}
 if(b.dataset.co){const value=b.dataset.co==='depart'?$('#co-seed')?.value||'':b.dataset.coValue||'';const r=G.symbiosisAction(state,b.dataset.co,b.dataset.coId||'',value);if(r.ok&&r.traveled){deathShown=false;cancelBuilding();close();view.camera={...state.player};}run(r);save();return;}
 if(b.dataset.control){const value=b.dataset.value;controls[b.dataset.control]=value==='true'?true:value==='false'?false:b.dataset.control==='ability'?value:Number(value);try{localStorage.setItem('jiuji.controls.v3',JSON.stringify(controls));}catch{notice('设备设置暂时无法保存。');}applyControls(document,controls);view.reducedMotion=controls.reducedMotion;view.particles=controls.particles;renderPanel();return;}
 if(b.dataset.recovery){try{const raw=localStorage.getItem(b.dataset.recovery),recovered=G.parseSave(raw);show('recovery-preview');$('#overlay').innerHTML=dialog('确认恢复','当前进度可先导出',`<p>恢复到 ${recovered.level} 级、第 ${G.day(recovered)} 天。</p><button data-do="export">先导出当前存档</button><button data-recovery-confirm="${b.dataset.recovery}">确认恢复这个存档</button>`);}catch(error){notice('恢复点不可读：'+error.message);}return;}
 if(b.dataset.recoveryConfirm){try{const recovered=G.parseSave(localStorage.getItem(b.dataset.recoveryConfirm));storeProgress(localStorage,SAVE_KEY,G.serialize(recovered),G.parseSave);state=recovered;deathShown=false;view.camera={...state.player};close();notice('恢复完成，替换前的进度保留在即时备份。');}catch(error){notice('恢复失败，当前进度未替换：'+error.message);}return;}
 if(b.dataset.target){run(G.interact(state,b.dataset.target));return;}
 if(b.dataset.photoPan){const [x,y]=b.dataset.photoPan.split(',').map(Number);view.camera.x+=x;view.camera.y+=y;return;}
 if(b.dataset.photoZoom){view.zoom=Math.max(.5,Math.min(1.6,view.zoom+Number(b.dataset.photoZoom)));return;}
 if(b.dataset.pin){state.wilderness.pinned=state.wilderness.pinned===b.dataset.pin?null:b.dataset.pin;save();renderPanel();updateWildernessHUD();return;}
 if(b.dataset.batch){run(G.craftBatch(state,b.dataset.batch,5));save();return;}
 if(b.dataset.do){perform(b.dataset.do);return;}
 if(b.dataset.manage){const machine=state.buildings.find(x=>x.id===b.dataset.manage);if(machine&&(['windmill','solararray','relay','assembler'].includes(machine.type)||(G.isOdyssey(state)&&['drill','synthesizer'].includes(machine.type))))show('odyssey',machine.id);else show('station',b.dataset.manage);return;}
 if(b.dataset.trial){const r=G.beginTrial(state,trialId,b.dataset.trial);run(r);if(r.ok)close();return;}
 if(b.dataset.repair){run(G.repair(state,b.dataset.repair));save();return;}
 if(b.dataset.transfer){run(G.transfer(state,stationId,b.dataset.item,b.dataset.transfer,Number(b.dataset.count)));save();return;}
 if(b.dataset.ending){run(G.chooseEnding(state,b.dataset.ending));save();return;}
 if(b.dataset.category){category=b.dataset.category;renderPanel();return;}
 if(b.dataset.openCategory){category=b.dataset.openCategory;show('craft');return;}
 if(b.dataset.craft){const r=G.craft(state,b.dataset.craft);if(r.placing)beginBuilding(r.placing);else run(r);save();return;}
 if(b.dataset.research){run(G.research(state,b.dataset.research));save();return;}
 if(b.dataset.use==='seed'){beginPlanting();return;}
 if(b.dataset.use){const r=G.useItem(state,b.dataset.use);run(r);save();return;}
 if(b.dataset.station){const r=G.stationAction(state,b.dataset.station,stationId);run(r);if(r.ok&&(['sleep','meditate','bait','dry'].includes(b.dataset.station)||b.dataset.station.startsWith('sow:')||b.dataset.station.startsWith('manifest:')||b.dataset.station.startsWith('cook:')))close();save();}
});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>2000000)throw new Error('存档超过大小限制');const imported=G.parseSave(await file.text());storeProgress(localStorage,SAVE_KEY,G.serialize(imported),G.parseSave);state=imported;deathShown=false;lastMessage=-1;cancelBuilding();view.camera={...state.player};save();close();notice('存档已导入，旅程继续。');}catch(error){notice('导入失败：'+error.message);}e.target.value='';});
const keyMap={KeyW:'up',ArrowUp:'up',KeyS:'down',ArrowDown:'down',KeyA:'left',ArrowLeft:'left',KeyD:'right',ArrowRight:'right'};
window.addEventListener('keydown',e=>{
 if(e.ctrlKey||e.metaKey||e.altKey)return;audio.unlock();
 if(panel&&e.code==='Tab'){const buttons=[...$('#overlay').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),summary')].filter(el=>el.getClientRects().length);if(buttons.length){const i=buttons.indexOf(document.activeElement),next=e.shiftKey?(i<=0?buttons.length-1:i-1):(i+1)%buttons.length;e.preventDefault();buttons[next].focus();}return;}
 if(e.code==='Escape'){e.preventDefault();if(panel==='photo'){perform('photo-close');return;}if(placing)cancelBuilding();else if(panel==='welcome')perform('start');else if(panel==='won')perform('freeplay');else if(panel==='dead')show('pause');else if(panel)close();else show('pause');return;}
 if(e.repeat){if(!panel&&['Space',...Object.keys(keyMap)].includes(e.code))e.preventDefault();return;}
 if(panel){if(panel==='welcome'&&e.code==='Enter')perform('start');return;}
 if(keyMap[e.code]){e.preventDefault();keys.add(e.code);}if(e.code==='ShiftLeft'||e.code==='ShiftRight')keys.add(e.code);
 if(e.code==='KeyE'){e.preventDefault();keys.add(e.code);perform('interact');}if(e.code==='Space'){e.preventDefault();keys.add(e.code);perform('attack');}
 const act={KeyC:'craft',KeyT:'tech',KeyB:'bag',KeyM:'map',KeyJ:'journey',KeyL:'missions',KeyF:'fuel',KeyG:'toggle-snap',KeyV:'dodge',KeyH:'bestiary',KeyQ:'dash',KeyR:'return',KeyN:'odyssey',KeyP:'projection'}[e.code];if(act&&(act!=='toggle-snap'||placing))perform(act);
 if(/^Digit[1-8]$/.test(e.code)){let id=hotIds[Number(e.code.slice(-1))-1];id=hotItem(id);if(id==='seed')beginPlanting();else run(G.useItem(state,id));}
});
window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',resetInput);document.addEventListener('visibilitychange',()=>{if(document.hidden){resetInput();save();}lastFrame=performance.now();});window.addEventListener('beforeunload',save);
for(const b of document.querySelectorAll('[data-move]')){b.addEventListener('pointerdown',e=>{e.preventDefault();if(panel)return;b.setPointerCapture(e.pointerId);moveTouch={x:({left:-1,right:1})[b.dataset.move]||0,y:({up:-1,down:1})[b.dataset.move]||0};});for(const type of['pointerup','pointercancel','lostpointercapture'])b.addEventListener(type,()=>moveTouch={x:0,y:0});}
bindStick($('#touch-stick'),v=>{moveTouch=panel?{x:0,y:0}:v;});
const attackButton=document.querySelector('.touch-actions [data-do="attack"]');attackButton.addEventListener('pointerdown',e=>{if(!panel){e.preventDefault();attackButton.setPointerCapture(e.pointerId);keys.add('Space');}});for(const event of ['pointerup','pointercancel','lostpointercapture'])attackButton.addEventListener(event,()=>keys.delete('Space'));
const canvas=$('#world');canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();view.pointer={x:e.clientX-r.left,y:e.clientY-r.top};view.hover=panel?null:view.hit(state,view.pointer.x,view.pointer.y);canvas.style.cursor=placing?'crosshair':view.hover?'pointer':'default';});canvas.addEventListener('pointerleave',()=>view.hover=null);
canvas.addEventListener('pointerdown',e=>{if(panel||e.button!==0)return;e.preventDefault();const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,p=view.toWorld(x,y);audio.unlock();if(placing){buildAt(placing!=='seed'&&view.snap?snapPoint(p):p);return;}const n=view.hit(state,x,y);if(n?.type==='enemy'){run(G.attack(state));return;}run(G.goTo(state,n?.x||p.x,n?.y||p.y,n?.id));canvas.focus({preventScroll:true});});
canvas.addEventListener('contextmenu',e=>{e.preventDefault();if(placing)cancelBuilding();});
window.addEventListener('jiuji:viewport',()=>{resetInput();view.resize();});
let firstFrame=true,lastDraw=0,lightingNoticed=false;
$('#world').addEventListener('contextlost',()=>{resetInput();save();show('render-recovery');});
$('#world').addEventListener('contextrestored',()=>{if(panel==='render-recovery')renderPanel();});
function loop(now){telemetry.update(state,!panel&&state.status==='playing',!document.hidden);const dt=Math.min(.1,(now-(lastFrame||now))/1000);lastFrame=now;if(!panel&&!document.hidden&&!view.contextLost){const x=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+moveTouch.x,y=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0)+moveTouch.y;G.step(state,dt,{x,y,sprint:keys.has('ShiftLeft')||keys.has('ShiftRight'),interact:keys.has('KeyE'),attack:keys.has('Space')});if(state.request){const r=state.request;state.request=null;run(r);}if(state.status!=='playing'&&!deathShown){deathShown=true;show(state.status==='won'?'won':'dead');save();}}
 audio.update(state);if((!panel||firstFrame||view.photo||view.needsRender)&&now-lastDraw>=1000/controls.fps-1){view.render(state,Math.min(.1,(now-lastDraw)/1000));view.needsRender=false;lastDraw=now;}if(view.simpleLighting&&!lightingNoticed){lightingNoticed=true;notice('当前设备已启用简化夜色，昼夜与生存规则保持不变。');}if(firstFrame){firstFrame=false;window.dispatchEvent(new Event('jiuji:ready'));}if(now-lastHud>250&&!panel){updateHUD();lastHud=now;}if(now-lastSave>5000&&!panel){save();lastSave=now;}if(now>toastUntil)$('#toast').classList.remove('show');requestAnimationFrame(loop);}
show('welcome');updateHUD();requestAnimationFrame(loop);

function chapterList(){return'<div class="requirements">'+G.chapterRequirements(state).map(r=>`<div class="requirement ${r.ok?'met':''}">${r.ok?'✓':'○'} ${r.text}</div>`).join('')+'</div>';}
function repairList(){return`<section class="repair-list"><h3>装备维护</h3><p class="subtle">研究台附近可修理：石制工具消耗 1 燧石、1 树枝；铜矛消耗 1 铜锭、1 木材；护甲消耗 3 纤维、1 木材。<br>林语弓：1 蛛丝、2 树枝；碎岩锤：3 石材、1 兽牙；霜晶长矛：2 霜晶、1 铜锭；余烬法杖：3 余烬核、2 木材。<br>弧光刃：1 合金、2 镜砂；棱镜长弓：2 星纤维、2 镜砂；引力锤：1 合金、2 星纤维。</p>${Object.entries(state.inventory).filter(([id,n])=>n&&G.ITEMS[id].durability).map(([id])=>`<div><span>${G.ITEMS[id].name} · ${state.durability[id]}/${G.ITEMS[id].durability}</span><button class="secondary" data-repair="${id}" ${!G.nearby(state,'table',185)||state.durability[id]>=G.ITEMS[id].durability?'disabled':''}>修理</button></div>`).join('')}</section>`;}
function storageList(b){return`<h3 class="section-title">${b.type==='synthesizer'?'生产储备 · 每 30 秒补充':'营地储物'}</h3><div class="storage-grid">${Object.keys(G.ITEMS).filter(id=>!G.ITEMS[id].durability&&((b.inventory?.[id]||0)||(state.inventory[id]||0))).map(id=>`<div class="storage-row">${icon(id)}<div><b>${G.ITEMS[id].name}</b><small>背包 ${state.inventory[id]||0} / 设施 ${b.inventory?.[id]||0}</small></div>${b.type==='chest'?`<button data-transfer="in" data-item="${id}" data-count="9999" ${(state.inventory[id]||0)?'':'disabled'}>存入</button>`:''}<button data-transfer="out" data-item="${id}" data-count="9999" ${(b.inventory?.[id]||0)?'':'disabled'}>取出</button></div>`).join('')||'<p class="subtle">暂时没有物品。</p>'}</div>`;}
function stationExtension(b){let html=wildStation(b)+homesteadStation(b);if(['seedbed','repairbench','trailpost','fieldkitchen','purifier','tidewell'].includes(b.type))html+=`<p class="subtle">岗位库存：${Object.entries(b.inventory||{}).map(([k,n])=>G.ITEMS[k].name+' ×'+n).join('、')||'空'}。投入一批后，在世界运行时处理。伙伴岗位需先在共生远征里安排伙伴。</p><button data-co="supply" data-co-id="${b.id}">投入一批材料</button><button data-co="collect" data-co-id="${b.id}">领取库存</button><button data-do="coexist">管理伙伴</button>`;if(['chest','synthesizer'].includes(b.type))html+=storageList(b);const c=G.CHAPTERS[state.level];if(c?.station===b.type)html+=`<h3 class="section-title">${state.level}级 → ${c.target}级 · ${G.LEVEL_NAMES[c.target]}</h3>${chapterList()}<button class="primary" data-station="ascend" ${G.chapterRequirements(state).every(r=>r.ok)?'':'disabled'}>晋升 ${c.target} 级</button>`;
 if(b.type==='forge')html+=`<h3 class="section-title">意念显化 · 每次 3 共鸣</h3><div class="manifest-grid">${Object.entries({wood:12,stone:10,ore:8,crystal:4,berry:8,grass:10,seed:6}).map(([id,n])=>`<button class="secondary" data-station="manifest:${id}">${G.ITEMS[id].name} ×${n}</button>`).join('')}</div><p class="subtle">显化后返回荒野，5 秒后可再次使用。</p>`;
 if(b.type==='garden')html+='<p class="subtle">每秒恢复 0.04 生态与 0.025 共鸣。三个不同区域的花园可以完成守序试炼。</p>';
 if(b.type==='gate')html+='<button class="secondary" data-do="return">归途传送 · 2 共鸣</button>';
 if(b.type==='archive')html+='<div class="journal">'+G.TRIALS.filter(t=>state.expansion.completed.includes(t.id)).map(t=>`<p><b>${t.name}</b>${t.options.find(o=>o.id===state.expansion.choices[t.id])?.name||'已完成'}</p>`).join('')+'</div>';
 if(b.type==='ascension'&&state.level===9)html+=state.expansion.ending?'<p class="subtle">你已经作出了自己的选择，世界仍在生长。</p>':`<h3 class="section-title">九级 · 你的最后一个选择</h3><div class="ending-choices"><button class="primary" data-ending="stay">留下守护<small>保留自己，在世界中继续生活。</small></button><button class="secondary" data-ending="return">归还星海<small>将记忆归于本源，完成这段旅程。</small></button></div>`;
 html+='<div class="station-maintenance"><button class="danger" data-do="dismantle">拆除设施</button><small>返还一半基础材料，需二次确认。</small></div>';return html;
}
function trialPanel(){const t=G.TRIALS.find(t=>t.id===trialId);if(!t)return dialog('遗迹','探索','没有找到这处遗迹。');const done=state.expansion.completed.includes(t.id);return dialog(t.name,'遗迹试炼 · '+t.level+'级',`<div class="station-visual">${icon('trial')}<p class="subtle">${t.intro}</p></div>${done?`<p class="subtle">你曾选择：${t.options.find(o=>o.id===state.expansion.choices[t.id])?.name}。这份记忆已经收入旅程。</p>`:t.options.map(o=>{const reason=G.trialReason(state,t.id,o.id);return`<article class="trial-option"><h3>${o.name}</h3><p>${o.text}</p>${costs(o.cost)}<button class="primary" data-trial="${o.id}" ${reason?'disabled':''}>${reason||'开始调谐'}</button></article>`;}).join('')}<p class="subtle">完成奖励：12 洞见、6 共鸣、1 记忆回响。<br>调谐时世界会继续运行；移动会中断，完成时才扣除材料。</p>`);}
function journeyPanel(){return dialog('九级 · 文明之路','从一根树枝，到整个星海',`<div class="journey-levels">${G.LEVEL_NAMES.slice(1).map((name,i)=>{const level=i+1,c=G.CHAPTERS[level];return`<article class="journey-level ${state.level===level?'current':''} ${state.level>level?'passed':''}"><div class="level-number">${G.LEVEL_ROMAN[level]}</div><div><h3>${name}<small>${state.level>level?'已抵达':state.level===level?'当前阶段':level+'级'}</small></h3><p>${G.LEVEL_BENEFITS[level]}</p>${c?`<small>晋升设施：${G.BUILDING_NAMES[c.station]} · ${G.TRIALS.find(t=>t.id===c.trial).name}</small>`:level===2?'<small>点亮高地信标，开启三级旅程。</small>':''}</div></article>`;}).join('')}</div><h3 class="section-title">遗迹坐标</h3><div class="trial-locations">${G.TRIALS.map(t=>`<div>${state.expansion.completed.includes(t.id)?'✓':'◇'} <b>${t.name}</b><span>${t.level}级 · ${t.x}, ${t.y}</span></div>`).join('')}</div>`,'遗迹位置在探索地图上以菱形标出。初始采矿会逐步过渡为自动生产与意念显化。');}
function updateAbilities(){const el=$('#abilities');if(!el)return;el.hidden=false;const a=state.expansion;setHTML('#abilities',`<button data-do="odyssey" title="N 文明控制台">文明</button>${state.level>=6&&state.tech.includes('projection')?`<button data-do="projection" title="P 投影臂 · 晶能 ${Math.floor(state.odyssey.power)} · 热量 ${Math.floor(state.odyssey.heat)}" aria-pressed="${state.odyssey.projection}">臂 ${Math.floor(state.odyssey.power)}</button>`:''}<button data-do="dodge" title="V 闪避，消耗 3 饱食"><kbd>V</kbd> 闪避${a&&state.expedition.dodgeCooldown>0?' '+Math.ceil(state.expedition.dodgeCooldown)+'s':''}</button><button data-do="bestiary"><kbd>H</kbd> 图鉴</button><button data-do="missions"><kbd>L</kbd> 委托${state.homestead.active?' ◇':''}</button>${state.level>=3?`<button data-do="dash" title="Q 闪步，消耗 4 意识"><kbd>Q</kbd> 闪步${a.dashCooldown>0?' '+Math.ceil(a.dashCooldown)+'s':''}</button>`:''}${state.level>=4?`<button data-do="return" title="R 归途，需折跃门和 2 共鸣"><kbd>R</kbd> 归途${a.returnCooldown>0?' '+Math.ceil(a.returnCooldown)+'s':''}</button>`:''}${state.homestead.satiety>0?`<span>行粮缓释 ${Math.ceil(state.homestead.satiety)}s</span>`:''}${state.homestead.channel?`<span>探索 ${Math.round(state.homestead.channel.elapsed/state.homestead.channel.duration*100)}%</span>`:''}${state.channel?`<span>调谐 ${Math.round(state.channel.elapsed/state.channel.duration*100)}%</span>`:''}`);}

function nearbyFacilities(){const list=state.buildings.filter(b=>G.distance(b,state.player)<=180);return '<h3 class="section-title">附近设施管理</h3><div class="manifest-grid">'+(list.map(b=>`<button class="secondary" data-manage="${b.id}">${G.BUILDING_NAMES[b.type]}</button>`).join('')||'<p class="subtle">靠近设施后可在这里管理与拆除。</p>')+'</div>';}

function updateWildernessHUD(){
 const season=G.season(state),temperature=Math.round(state.living.temperature);
 const w=G.weather(state),wet=Math.round(state.wilderness.wetness),covered=G.shelterAt(state),warm=G.nearby(state,'campfire',165);
 setHTML('#weather',`<span style="color:${season.color}">${season.name} ${season.day}/4 · ${temperature}℃</span><span>${w.raining?'☂ 林间阵雨':w.warning?'☁ 雨云将至':'☼ 天气晴朗'}</span><b class="${wet>65?'soaked':''}">${covered?'庇护中'+(wet?' · 湿度 '+wet+'%':''):warm&&wet?'烘干中 · '+wet+'%':wet?'湿度 '+wet+'%':'衣物干燥'}</b>${w.raining?`<small>约 ${Math.ceil(w.remaining)} 秒后停雨</small>`:w.warning?'<small>备好柴火，回到庇护所</small>':''}`);
 const handbook=$('[data-do="handbook"]');if(handbook)handbook.title='生存手册 · '+G.HANDBOOK.filter(h=>!state.living.claimed.includes(h.id)&&h.progress(state)>=h.goal).length+' 项奖励待领取';
 const button=$('[data-do="sound"]');button.textContent=audio.muted?'音效 关':'音效 开';button.setAttribute('aria-pressed',String(!audio.muted));
 const r=G.RECIPES.find(r=>r.id===state.wilderness.pinned),el=$('#pinned');el.hidden=!r;
 if(r)setHTML('#pinned',`<div><strong>制作清单 · ${r.name}</strong><button data-do="unpin" aria-label="取消材料追踪">×</button></div>${costs(r.cost,true)}<div class="co-sources">${materialSources(state,r).map(m=>`<p>${G.ITEMS[m.item]?.name||G.RESOURCE_NAMES[m.item]} 缺 ${m.missing} · ${m.source}${m.node?` <button data-co-walk="${m.node.id}">前往</button>`:''}</p>`).join('')}</div><button class="secondary" data-craft="${r.id}" ${G.recipeReason(state,r)?'disabled':''}>${r.building?'选择位置':'制作'}</button>`);
}
function wildStation(b){
 if(b.type==='shelter')return '<p class="subtle">遮雨范围：125 步。进入范围后停止淋湿，并缓慢晾干。<br>在附近搭建营火，可以更快烘干衣物。毛皮披肩让外出时淋雨速度降低 75%。</p>';
 if(!['cookpot','trap'].includes(b.type))return '';
 const stock=Object.entries(b.inventory||{}).filter(([,n])=>n>0);let html='';
 if(stock.length)html+=`<div class="harvest-ready">${stock.map(([id,n])=>`${icon(id)}<span>${G.ITEMS[id].name} ×${n}</span>`).join('')}<button class="primary" data-station="collect">领取全部</button></div>`;
 else if(b.kitchen||b.baitAt)html+=`<div class="cooking-progress"><h3>${b.kitchen?'锅里咕嘟作响':'诱饵已经放好'}</h3><p>还需 ${Math.ceil((b.kitchen?.readyAt||b.baitAt)-state.time)} 秒。返回荒野后计时继续，可以先去采集。</p><button class="primary" data-do="close">继续在营地活动</button></div>`;
 else if(b.type==='trap')html+=`<p class="subtle">投入一颗浆果，60 秒后获得 2 生肉、1 毛皮。<br>诱捕在后台进行，离开营地仍会继续。</p>${costs({berry:1})}<button class="primary" data-station="bait" ${state.inventory.berry?'':'disabled'}>放置诱饵</button>`;
 else html+='<div class="dish-grid">'+G.DISHES.map(d=>`<article class="recipe">${icon(d.id,'recipe-image')}<div><h3>${d.name}</h3><p>${d.text}</p>${costs(d.cost,true)}<button class="primary" data-station="cook:${d.id}" ${G.craftAffordable(state,d.cost)?'':'disabled'}>炖煮 · ${d.seconds} 秒</button></div></article>`).join('')+'</div>';
 return html;
}

function handbookPanel(){
 const season=G.season(state),temp=Math.round(state.living.temperature);
 return dialog('荒野生存手册','把每一件小事，变成旅程',`<div class="growth-callout"><b>不知道共鸣和生态怎么提升？</b><p>播种青杉从开局即可进行；研究万物观察后，在燃烧的营火旁冥想。</p><button class="secondary" data-do="growth">查看成长指引</button></div><section class="season-card" style="--season:${season.color}"><h3>${season.name} · 第 ${season.day} / 4 天</h3><p>${season.tip}</p><p>体感 ${temp}℃ · ${temp<6?'寒冷：寻找营火、披肩或喝鱼汤':temp>33?'炎热：前往庇护所避暑':'体感舒适'}<br>约 ${Math.ceil(season.remaining/60)} 分钟后进入${season.next}，世界暂停时不计时。</p><div class="season-strip">${['新芽春','长昼夏','丰收秋','静雪冬'].map((n,i)=>`<span class="${i===season.index?'active':''}">${n}</span>`).join('')}</div></section><div class="handbook-grid">${G.HANDBOOK.map(h=>{const value=Math.min(h.goal,h.progress(state)),claimed=state.living.claimed.includes(h.id);return `<article class="handbook-card ${claimed?'completed':''}"><h3>${claimed?'✓ ':''}${h.name}<small>${value} / ${h.goal}</small></h3><p>${h.text}</p><progress value="${value}" max="${h.goal}" aria-label="${h.name}进度"></progress><p class="reward">奖励：${Object.entries(h.reward).map(([id,n])=>G.RESOURCE_NAMES[id]+' ×'+n).join('、')}</p><button class="${value>=h.goal&&!claimed?'primary':'secondary'}" data-claim="${h.id}" ${claimed||value<h.goal?'disabled':''}>${claimed?'已领取':value<h.goal?'继续探索':'领取奖励'}</button></article>`;}).join('')}</div><p class="subtle">钓鱼：合成枝编钓竿，地图蓝色标记处寻找鱼塘，靠近点击或按 E。移动会中断等待。低于 6℃ 或高于 33℃ 会额外消耗饱食与意识；八级后不再受体温影响。</p>`,'每季四个游戏日。每条手册奖励只可领取一次。');
}

function realmCards(){return '<div class="realm-cards">'+Object.entries(G.REALMS).map(([id,r])=>`<article style="--realm:${r.color}" class="${id===state.expedition.current?'current':''}"><small>${state.expedition.visited.includes(id)?'已抵达':'未探索'} · ${r.level}级</small><b>${r.name}</b><span>${r.subtitle}</span></article>`).join('')+'</div>';}
function riftPanel(){const n=state.nodes.find(n=>n.id===stationId);if(!n)return dialog('裂隙已消失','虫洞','请重新靠近虫洞。');const r=G.REALMS[n.destination],reason=G.portalReason(state,n);return dialog('虫洞 · '+r.name,'RIFT EXPEDITION',`<div class="rift-hero">${icon('wormhole')}<div><h3>${r.subtitle}</h3><p>${r.tip}</p><p>需要 ${r.level} 级 · 往返不消耗材料</p></div></div>${realmCards()}<p class="subtle">背包、科技与手册随你远行。每张地图保留自己的营地、资源、迷雾和野怪。离开的地图暂停生产与刷新，回来后继续计时。</p><button class="primary" data-do="cross-rift" ${reason?'disabled':''}>${reason||'踏入虫洞 →'}</button>`);}
function bestiaryPanel(){const weapon=G.equippedWeapon(state);return dialog('远征图鉴','认识危险，然后准备出发',`<div class="expedition-overview"><b>已探索 ${state.expedition.visited.length}/4 张地图</b><b>守卫 ${state.expedition.bosses.length}/3</b><span>装备：${G.ITEMS[weapon]?.name||'徒手'}</span></div><p class="subtle">红色圈标出即将发生的攻击；蓄力结束前离开圈内，或按 V 闪避。虫洞入口附近是安全落脚地。普通野怪击败后，当前地图活动四分钟后重新出现；区域守卫不会重生。</p><h3>武器与补给</h3><div class="bestiary-grid">${Object.entries(G.WEAPONS).map(([id,w])=>`<article>${icon(id)}<h3>${G.ITEMS[id].name}</h3><p>${w.text}${SPECIALTIES[id]?.[state.homestead.specialty[id]]?' · '+SPECIALTIES[id][state.homestead.specialty[id]].name:''}</p><small>伤害 ${G.effectiveWeapon(state,id).damage} · 射程 ${G.effectiveWeapon(state,id).range} · 间隔 ${G.effectiveWeapon(state,id).cooldown}s</small>${state.inventory[id]?`<button class="secondary" data-use="${id}">${weapon===id?'已装备':'装备'} · ${state.durability[id]} 耐久</button>`:''}</article>`).join('')}</div><h3>荒野生灵</h3><div class="bestiary-grid">${Object.entries(G.CREATURES).map(([id,m])=>`<article>${icon(id)}<h3>${m.name}${m.boss?' · 守卫':''}</h3><small>生命 ${m.hp} · 击败 ${state.expedition.kills[id]||0} 次</small><p>${m.tip}</p><small>掉落：${Object.entries(m.drop).map(([k,n])=>G.ITEMS[k].name+' ×'+n).join('、')}</small></article>`).join('')}</div>`,'远征是额外冒险，不要求击败野怪才能推进原有九级主线。');}

function growthPanel(){
 const g=growthStatus(state),camp=g.camp;
 return dialog('共鸣与生态，从哪里来','荒野共生 · 成长指引',`<div class="growth-summary"><span>共鸣 <b>${Math.floor(state.resonance)}</b></span><span>生态 <b>${Math.round(state.ecology)}/100</b></span><span>已播种 <b>${state.stats.planted} 株</b></span></div><div class="growth-grid"><section class="growth-card"><h3>① 先播种青杉 · 开局可用</h3><p>采集浆果丛或砍伐青杉获得种子。在合成「营地 / 生存」、背包或快捷栏第 7 格选择种子，再点击身边空地；也可以使用「身边空地播种」。</p><p><strong>每株消耗 1 种子：生态 +3，85 秒成长后共鸣 +1。</strong>播种满三次，再研究「共生实践」解锁循环农圃。建农圃不会计入播种次数。</p><p class="growth-state">共生实践播种进度 ${g.planted}/3 · 种子 ${G.amount(state,'seed')}<br>${g.saplings?`当前地图 ${g.saplings} 株树苗 · 最近一株约 ${g.nextGrowth} 秒后成长`:'当前地图没有等待成长的树苗'}。世界暂停、离开当前地图时不计时。</p><button class="primary" data-do="plant" ${state.inventory.seed?'':'disabled'}>选择空地播种</button>${!state.inventory.seed?'<p class="reason">先采集浆果丛或砍伐青杉，获得种子。</p>':''}</section><section class="growth-card"><h3>② 营火冥想 · 获得共鸣</h3><p>在研究台旁掌握「万物观察」，带上荧光花，走近燃烧的营火选择冥想。<strong>1 朵荧光花 → 4 共鸣、18 意识，间隔 12 秒。</strong></p><p>共鸣用于研究和晋升；意识是角色的生存状态，两者不同。采集荧光花会获得花朵，需通过冥想转化成共鸣。调查先行者遗迹可获得 3 共鸣，手册的「归还给土地」奖励另有 4 共鸣。</p><p class="growth-state">万物观察 ${state.tech.includes('observe')?'已掌握':'未掌握'} · 荧光花 ${G.amount(state,'flower')}<br>${g.meditationReason||'条件满足，现在可以冥想'}${state.meditationCooldown>0?'；返回荒野后冷却继续':''}。</p><button class="primary" data-do="meditate-nearby" ${g.meditationReason?'disabled':''}>在附近营火冥想</button>${camp?'<button class="secondary" data-do="guide-camp">前往当前地图营火</button>':'<button class="secondary" data-open-category="camp">建造营火与研究台</button>'}<button class="text-help" data-do="tech">打开科技树</button></section><section class="growth-card"><h3>③ 边采集，边修复生态</h3><p>砍一株青杉生态 −1.2，种一株青杉 +3；开采岩石 −0.3、铜矿 −0.8、原晶 −0.5。保留部分种子补种，可以持续恢复生态，最高 100。</p><p>循环农圃建成后缓慢恢复生态，收获再加 1。七级生态花园可持续恢复生态与共鸣。普通青杉砍伐后不会自行再生，需要播种补植。</p><button class="secondary" data-do="handbook">打开生存手册与奖励</button><button class="secondary" data-open-category="camp">查看营地配方</button></section><section class="growth-card"><h3>④ ${state.level<9?state.level+'级 → '+(state.level+1)+'级 · 当前条件':'九级 · 继续探索'}</h3>${state.level===9?'<p>在归一星环完成结局选择，或继续建设家园。</p>':growthRequirementList()}<p class="growth-state">共鸣用于晋升时会消耗。一级的共鸣台还需 4 共鸣建造，研究、建造后请再储备 8 共鸣启动。</p><button class="secondary" data-do="tech">查看当前科技</button><button class="secondary" data-do="journey">查看九级历程</button><button class="primary" data-do="guide-promotion">定位 / 建造晋升设施</button></section></div>`,'数值均为当前进度；研究、冥想和播种都按实际条件执行。');
}

function journeyChoices(){return `<div class="journey-choices"><button data-campaign="odyssey" class="${newCampaign==='odyssey'?'selected':''}"><b>共生远征 · 3.0</b><small>六地成长、裂隙探索、营地伙伴与装备模块</small></button><button data-campaign="classic" class="${newCampaign==='classic'?'selected':''}"><b>经典旅程</b><small>保留原有晋级规则，新地图可自由探索</small></button><label>世界种子<input id="world-seed" name="world-seed" inputmode="numeric" maxlength="10" value="${escape(newSeed)}" aria-label="世界种子"></label><small>相同种子生成相同资源分布；不同种子可重新探索。</small></div>`;}
function startConfiguredGame(){const field=$('#world-seed');if(field)newSeed=field.value.trim();const seed=Number(newSeed);if(!/^\d+$/.test(newSeed)||!Number.isInteger(seed)||seed<1||seed>4294967295){notice('世界种子需要是 1～4294967295 的整数。');return false;}state=newCampaign==='odyssey'?G.createOdysseyGame(seed,newDifficulty):G.createGame(seed,newDifficulty);return true;}
document.addEventListener('input',e=>{if(e.target.id==='world-seed')newSeed=e.target.value;});
function difficultyChoices(mode){return`<div class="difficulty-choices"><button data-difficulty="survival" class="${mode==='survival'?'selected':''}"><b>求生</b><small>死亡后重新出发<br>保留经典生存压力</small></button><button data-difficulty="explore" class="${mode==='explore'?'selected':''}"><b>探索</b><small>原岛营火重生<br>返回遗落包找回材料</small></button></div>`;}
function missionsPanel(){
 const h=state.homestead,active=CONTRACTS.find(c=>c.id===h.active),desk=G.inHome(state)&&G.nearby(state,'fielddesk',180);
 const activeCard=active?`<section class="contract-active"><small>当前委托 · ${G.REALMS[active.map].name}</small><h3>${active.name}</h3><p>${active.text}</p><p>${contractProgress(state,active)?'✓ 探索已完成，返回原岛手记台交付':'○ 穿过虫洞，到目标地图寻找金色菱形探索点'}</p><button class="primary" data-do="claim-contract" ${desk&&contractProgress(state,active)?'':'disabled'}>交付委托</button>${!desk?'<p>回原岛后走近远征手记台，才能交付。</p>':''}</section>`:'<p class="subtle">任选一项委托开始。探索点也可先行探索，随后带成果回营交付。没有现实时间每日签到。</p>';
 return dialog('远征有了归处','3.0.1 · 共生远征',`<div class="expedition-overview"><b>委托 ${h.completed.length}/9</b><b>探索点 ${h.sites.length}/18</b><span>古代构件 ${G.amount(state,'relicpart')}</span></div>${!desk?'<div class="growth-callout"><b>原岛远征手记台</b><p>在营地分类建造，走近后接受和交付。升级用的古代构件也能通过非战斗探索获得。</p><button class="secondary" data-open-category="camp">查看营地设施</button></div>':''}${activeCard}<div class="contract-grid">${CONTRACTS.map(c=>{const done=h.completed.includes(c.id),locked=state.level<G.REALMS[c.map].level;return`<article class="contract-card ${done?'completed':''}"><small>${G.REALMS[c.map].level}级地图 · ${done?'已交付':contractProgress(state,c)?'成果已备齐':'待探索'}</small><h3>${c.name}</h3><p>${c.text}</p><p class="reward">奖励：${Object.entries(c.reward).map(([id,n])=>G.ITEMS[id].name+' ×'+n).join('、')}</p><button class="secondary" data-contract="${c.id}" ${done||h.active||!desk||locked?'disabled':''}>${done?'已交付':h.active===c.id?'追踪中':locked?'需要 '+G.REALMS[c.map].level+' 级':'接受委托'}</button></article>`;}).join('')}</div><h3 class="section-title">武器专长 · 每次消耗 1 古代构件</h3><p class="subtle">在远征手记台附近选择，需持有武器。切换专长同样消耗构件。构件还用于升级营地，请选择最需要的用途。</p><div class="specialty-grid">${Object.entries(SPECIALTIES).map(([weapon,choices])=>`<section class="growth-card"><h3>${G.ITEMS[weapon].name}</h3>${Object.entries(choices).map(([id,sp])=>`<div class="specialty-choice"><b>${sp.name}${h.specialty[weapon]===id?' ✓':''}</b><p>${sp.text}</p><button class="secondary" data-specialty="${weapon}:${id}" ${!G.nearby(state,'fielddesk',180)||!state.inventory[weapon]||!state.inventory.relicpart||h.specialty[weapon]===id?'disabled':''}>${h.specialty[weapon]===id?'已选择':'选择专长'}</button></div>`).join('')}</section>`).join('')}</div><h3 class="section-title">遗落包 ${h.graves.length} 处</h3><p class="subtle">${h.graves.length?h.graves.map(g=>G.REALMS[g.realm].name+' · '+Object.entries(g.inventory).filter(([,n])=>n).map(([id,n])=>G.ITEMS[id].name+' ×'+n).join('、')).join('<br>'):'探索模式可在死亡后回原岛营火，装备和食物保留，半数普通材料留在原地，可返回取回。难度在新旅程开始前选择。'}</p>`,'两种修复方案都能获得构件，各有材料与时间代价。升级营地后再规划下一趟远征。');
}
function fieldsitePanel(){const n=state.nodes.find(n=>n.id===stationId),site=SITE_TYPES[n?.siteType];if(!site)return dialog('探索点','荒野遭遇','请重新走近探索点。');return dialog(site.name,G.REALMS[n.realm].name,`<div class="site-hero">${icon(site.icon)}<p>${site.text}</p></div><div class="contract-grid">${site.options.map(o=>{const reason=siteChoiceReason(n,o);return`<article class="contract-card"><h3>${o.name}</h3>${costs(o.cost)}<p>原地进行 ${o.seconds} 秒。完成时才扣材料；移动、攻击或受伤会中断。</p><p class="reward">所得：${[...Object.entries(o.drop).map(([id,v])=>G.ITEMS[id].name+' ×'+v),o.insight?'洞见 +'+o.insight:'',o.resonance?'共鸣 +'+o.resonance:'',o.eco?'生态 +'+o.eco:''].filter(Boolean).join('、')}</p><button class="primary" data-site-choice="${o.id}" ${reason?'disabled':''}>${reason||'开始探索'}</button></article>`;}).join('')}</div>`,'每处探索点只能完成一次。虫洞往返与读档不会刷新奖励。');}
function siteChoiceReason(n,o){if(!n.available||state.homestead.sites.includes(n.id))return'已经完成';if(G.distance(state.player,n)>140)return'请先走近';if(!G.affordable(state,o.cost))return'背包材料不足';return'';}
function homesteadStation(b){
 if(b.type==='fielddesk')return'<button class="primary" data-do="missions">远征委托与武器专长</button><button class="secondary" data-do="settlement">营地经营与远征回信</button><button class="secondary" data-do="odyssey">2.0 文明控制台</button>';
 if(!['nursery','dryingrack'].includes(b.type))return'';
 const ready=Object.entries(b.inventory||{}).filter(([,n])=>n>0);
 if(ready.length)return`<div class="harvest-ready">${ready.map(([id,n])=>`${icon(id)}<span>${G.ITEMS[id].name} ×${n}</span>`).join('')}<button class="primary" data-station="home-collect">领取营地产物</button></div>`;
 if(b.crop)return`<div class="cooking-progress"><h3>${b.type==='nursery'?'作物正在生长':'行粮正在晾晒'}</h3><p>还需 ${Math.max(0,Math.ceil(b.crop.readyAt-state.time))} 秒。返回荒野后继续计时；离开当前地图暂停。${b.improved?'已改良：本轮耗时减少 20%。':''}</p>${b.type==='nursery'?`${costs({compost:1},true)}<button class="secondary" data-station="fertilize" ${b.crop.fertilized||!G.craftAffordable(state,{compost:1})?'disabled':''}>${b.crop.fertilized?'本轮已追肥':'堆肥追肥 · 剩余时间减少 40%'}</button>`:''}<button class="primary" data-do="close">回营地活动</button></div>`;
 if(b.type==='dryingrack')return`<p class="subtle">4 浆果、1 生肉 → 1 风干行粮，晾晒 ${b.improved?56:70} 秒。食用饱食 +60、生命 +10，120 秒内饥饿消耗减少 40%。可取用附近箱子。</p>${costs({berry:4,meat:1},true)}<button class="primary" data-station="dry" ${G.craftAffordable(state,{berry:4,meat:1})?'':'disabled'}>开始晾晒</button>`;
 return'<p class="subtle">青杉补植修生态，育苗床生产作物。每次只种一类，收获后重新播种；偏好季节生长更快。</p><div class="contract-grid">'+Object.entries(CROPS).map(([id,c])=>`<article class="contract-card">${icon(id==='flower'?'flower':id)}<h3>${c.name}</h3><p>${c.tip}</p>${costs(c.cost,true)}<p>收获：${Object.entries(c.drop).map(([key,n])=>G.ITEMS[key].name+' ×'+n).join('、')}</p><button class="primary" data-station="sow:${id}" ${G.craftAffordable(state,c.cost)?'':'disabled'}>播种${c.name}</button></article>`).join('')+'</div>';
}

function frontierReward(drop){return Object.entries(drop||{}).map(([id,n])=>G.RESOURCE_NAMES[id]+' ×'+n).join('、')||'记录留在旅程中';}
function frontierStation(b){
 let html='';
 if(IMPROVE_COST[b.type]){const reason=improveReason(state,b);html+=`<section class="frontier-upgrade"><b>${b.improved?'✦ 已改良':'设施改良'}</b><p>育苗与晾晒耗时减少 20%，工坊订单耗时减少 25%。永久生效，不改变已经投入的订单。</p>${!b.improved?costs(IMPROVE_COST[b.type],true)+`<button class="secondary" data-station="improve" ${reason?'disabled':''}>${reason||'改良这处设施'}</button>`:''}</section>`;}
 if(!['composter','relaywork','matterloom','aidbeacon'].includes(b.type))return html;
 const stock=Object.entries(b.inventory||{}).filter(([,n])=>n>0);
 if(stock.length)html+=`<div class="harvest-ready">${stock.map(([id,n])=>`${icon(id)}<span>${G.RESOURCE_NAMES[id]} ×${n}</span>`).join('')}<button class="primary" data-station="frontier-collect">领取产物与回赠</button></div>`;
 else if(b.project||b.aid){const a=b.project||b.aid;html+=`<div class="cooking-progress"><h3>${b.project?JOBS[a.id].name+' · '+a.count+' 批':AID_MAPS[a.map].name}</h3><p>还需 ${Math.ceil(a.remaining)} 秒当前地图活动。暂停、离线、离开地图均不推进；订单材料已投入，拆除会失去在制品。</p><button class="primary" data-do="close">回到营地，继续生活</button></div>`;}
 else if(b.type==='aidbeacon')html+='<div class="frontier-grid">'+Object.entries(AID_MAPS).map(([map,a])=>`<section class="growth-card"><h3>${a.name}</h3><p>${a.text}</p><p>完成 ${state.frontier.aidDone[map]||0} 次 · ${state.frontier.aidCooldown[map]>0?'等待 '+Math.ceil(state.frontier.aidCooldown[map])+' 秒有效游玩':'可商议下一轮援助'}</p>${a.options.map(o=>{const r=aidReason(state,b,map,o.id);return`<div class="specialty-choice"><b>${o.name}</b><p>${o.text}</p>${costs(o.cost,true)}<p class="reward">回信：${frontierReward(o.drop)} · 生态 +3</p><button class="secondary" data-station="aid:${map}:${o.id}" ${r?'disabled':''}>${r||'提供物资 · 100 秒'}</button></div>`;}).join('')}</section>`).join('')+'</div>';
 else html+='<div class="frontier-grid">'+Object.entries(JOBS).filter(([,j])=>j.station===b.type).map(([id,j])=>{const r=jobReason(state,b,id),r3=jobReason(state,b,id,3);return`<article class="growth-card">${icon(Object.keys(j.drop)[0],'frontier-icon')}<h3>${j.name} · ${j.level}级</h3><p>${j.text}${b.improved?' 已改良，生产耗时再减少 25%。':''}</p>${costs(j.cost,true)}<p class="reward">每批产出：${frontierReward(j.drop)}</p><div class="frontier-buttons"><button class="primary" data-station="job:${id}:1" ${r?'disabled':''}>${r||'安排一批'}</button><button class="secondary" data-station="job:${id}:3" ${r3?'disabled':''}>安排三批</button></div><small>三批一次投入三倍材料，全部完成后一起领取。</small></article>`;}).join('')+'</div>';
 if(b.type==='composter')html+=`<section class="growth-callout"><b>给土地补养</b><p>1 堆肥 → 生态 +4。育苗床生长时也可追肥，每轮一次，剩余时间减少 40%。</p>${costs({compost:1},true)}<button class="secondary" data-station="soil" ${G.craftAffordable(state,{compost:1})&&state.ecology<100?'':'disabled'}>照料营地土壤</button></section>`;
 return html;
}
function settlementPanel(){
 const f=state.frontier,nearDesk=G.inHome(state)&&G.nearby(state,'fielddesk',180),facilities=state.buildings.filter(b=>['nursery','dryingrack','composter','relaywork','matterloom','aidbeacon'].includes(b.type));
 const returns=f.deliveries.length?f.deliveries.map(d=>{const e=ENCOUNTERS.find(e=>e.id===d.id),o=e.options.find(o=>o.id===f.choices[d.id]);return`<article class="growth-card"><h3>${e.name} · 回信</h3><p>${frontierReward(o.later)}</p><p>${d.remaining>0?'还需 '+Math.ceil(d.remaining)+' 秒有效游玩':'物资已到达原岛手记台'}</p><button class="primary" data-delivery="${d.id}" ${nearDesk&&!d.remaining?'':'disabled'}>${!nearDesk?'回原岛手记台领取':d.remaining?'回信仍在途中':'拆开回信，领取物资'}</button></article>`;}).join(''):'<p class="subtle">部分远征事件会留下延迟回报。它们按有效游玩计时，抵达后到原岛手记台领取。</p>';
 const cards=facilities.length?facilities.map(b=>{const active=b.project||b.aid,ready=Object.values(b.inventory||{}).some(n=>n>0),near=G.distance(state.player,b)<=180;return`<article class="growth-card">${icon(b.type,'frontier-icon')}<h3>${G.BUILDING_NAMES[b.type]}${b.improved?' ✦':''}</h3><p>${active?'运转中 · '+Math.ceil(active.remaining)+' 秒':b.crop?'生长 / 加工中 · '+Math.max(0,Math.ceil(b.crop.readyAt-state.time))+' 秒':ready?'产物已就绪':'等待你的安排'}</p><button class="secondary" ${near?'data-manage':'data-walk-facility'}="${b.id}">${near?'管理设施':'走到设施旁'}</button></article>`;}).join(''):'<p class="subtle">这张地图还没有经营设施。先完成首项远征委托，建育苗床与晾晒架；二级可建堆肥箱。</p>';
 return dialog('营地有了新的生活','3.0.1 · 共生远征',`<div class="civ-entry"><button class="primary" data-do="odyssey">文明控制台 · 晶能 / 物流 / 六地任务</button><p>2.0 星海回响：走进每一阶真正解锁的新玩法。</p></div><div class="frontier-banner"><div><small>把远行带回家</small><h3>照料土地，接续远方</h3><p>当前：${G.realm(state).name} · 只推进所在地图的生产</p></div>${icon('relaywork')}</div><div class="expedition-overview"><b>遭遇 ${Object.keys(f.choices).length}/9</b><b>生产 ${f.orders} 批</b><span>照料 ${f.care} 次 · 援助 ${Object.values(f.aidDone).reduce((a,b)=>a+b,0)} 次</span></div><h3>当前地图 · 设施总览</h3><div class="frontier-grid">${cards}</div><button class="secondary" data-open-category="advanced">查看文明设施配方</button><button class="secondary" data-open-category="camp">查看营地配方</button><h3 class="section-title">远征回信</h3><div class="frontier-grid">${returns}</div><h3 class="section-title">每一阶，多一种选择</h3><div class="frontier-grid">${[[2,'林地堆肥箱','把种子与纤维变成堆肥，追肥或补养土地。'],[4,'共振工坊','以原晶、荧光花与共鸣凝结星露。'],[5,'构件修缮','把陨星碎片、铜锭与星露修成古代构件。'],[6,'循环织造台','用星露和共鸣换建材或林地补给。'],[7,'远方守护台','先理解远征营地，再选择援助物资与回赠。']].map(([lv,name,desc])=>`<article class="growth-card ${state.level<lv?'frontier-locked':''}"><small>${state.level>=lv?'✓ 已到达':'○ 待晋升'} · ${lv}级</small><h3>${name}</h3><p>${desc}</p></article>`).join('')}</div><h3 class="section-title">远征遭遇 · 选择记录</h3><p class="subtle">每张远征地图新增三处青绿色星标遭遇。完成后不会刷新；回信领取一次。部分事件可以选择不投入物资的记录路线，也可以暂时离开，准备好再回来。</p><div class="frontier-grid">${ENCOUNTERS.map(e=>{const choice=e.options.find(o=>o.id===f.choices[e.id]),n=state.nodes.find(n=>n.eventId===e.id);return`<article class="growth-card"><small>${G.REALMS[e.map].name}</small><h3>${choice?'✓ ':''}${e.name}</h3><p>${choice?'已选择：'+choice.name:e.text}</p>${!choice&&n?`<button class="secondary" data-walk-facility="${n.id}">前往遭遇地点</button>`:!choice?'<small>穿过虫洞，在当地打开地图寻找星标。</small>':''}</article>`;}).join('')}</div>`,'共鸣用于生产，也用于晋升。订单材料预先投入，拆除不会返还在制品。');
}
function encounterPanel(){const n=state.nodes.find(n=>n.id===stationId),e=ENCOUNTERS.find(e=>e.id===n?.eventId);if(!e)return dialog('远征遭遇','荒野手记','请重新走近事件。');return dialog(e.name,G.REALMS[e.map].name,`<div class="frontier-story">${icon(e.icon)}<p>${e.text}</p></div><div class="frontier-grid">${e.options.map(o=>{const reason=encounterReason(state,e.id,o.id);return`<article class="growth-card"><h3>${o.name}</h3>${costs(o.cost)}<p>${o.text}</p><p class="reward">立即：${frontierReward(o.drop)}${o.insight?' · 洞见 +'+o.insight:''}</p>${o.later?`<p class="reward">回信：${frontierReward(o.later)} · ${o.delay} 秒有效游玩后到原岛领取</p>`:''}<button class="primary" data-encounter-choice="${o.id}" ${reason?'disabled':''}>${reason||'作出这个选择'}</button></article>`;}).join('')}</div>`,'每处事件只作一次选择；需要背包材料。可以关上面板，准备后再回来。');}
